function normaliseWorldPresence(payload) {
  if (!payload?.friends) return payload;
  payload.friends.forEach((row) => (row.spans || []).forEach((span) => {
    if (span.world_id) return;
    const location = String(span.location || '').trim().toLowerCase();
    if (location === 'private' || location.startsWith('private:')) span.world_id = '__private__';
    else if (location === 'traveling' || location === 'travel') span.world_id = '__traveling__';
    else if (location === 'offline' || span.status === 'offline') span.world_id = '__offline__';
    else span.world_id = '__location_hidden__';
  }));
  return payload;
}
