function renderTrend() { const canvas = $('trendChart'); const ctx = canvas.getContext('2d'); const width = canvas.clientWidth * devicePixelRatio; const height = 190 * devicePixelRatio; canvas.width = width; canvas.height = height; ctx.scale(devicePixelRatio, devicePixelRatio); const w = canvas.clientWidth, h = 190; ctx.clearRect(0,0,w,h); const daily = stats.daily_changes || []; const labels = []; const values = []; for (let i=6;i>=0;i--) { const date = new Date(Date.now()-i*86400000); const key = date.toISOString().slice(0,10); labels.push(key.slice(5)); values.push((daily.find((x) => x.day === key) || {}).changes || 0); } const max = Math.max(4, ...values); ctx.strokeStyle='#2a303c'; ctx.lineWidth=1; for (let i=0;i<4;i++){const y=18+i*40;ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(w,y);ctx.stroke()} ctx.beginPath(); values.forEach((v,i)=>{const x=10+i*(w-20)/6; const y=150-(v/max)*118; i?ctx.lineTo(x,y):ctx.moveTo(x,y)}); ctx.lineTo(w-10,150);ctx.lineTo(10,150);ctx.closePath();ctx.fillStyle='#b7f36b12';ctx.fill();ctx.beginPath();values.forEach((v,i)=>{const x=10+i*(w-20)/6;const y=150-(v/max)*118;i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.strokeStyle='#b7f36b';ctx.lineWidth=2;ctx.stroke();values.forEach((v,i)=>{const x=10+i*(w-20)/6;const y=150-(v/max)*118;ctx.fillStyle='#b7f36b';ctx.beginPath();ctx.arc(x,y,3,0,Math.PI*2);ctx.fill();ctx.fillStyle='#6d7585';ctx.font='10px DM Mono';ctx.fillText(labels[i],x-13,176)}); }
const localDateKey = () => { const now = new Date(); const parts = new Intl.DateTimeFormat('en-CA', {year:'numeric', month:'2-digit', day:'2-digit'}).formatToParts(now); return `${parts.find((x) => x.type === 'year').value}-${parts.find((x) => x.type === 'month').value}-${parts.find((x) => x.type === 'day').value}`; };
const dateKeyOffset = (key, offset) => { const value = new Date(`${key}T12:00:00`); value.setDate(value.getDate() + offset); return localDateKeyFromDate(value); };
function normaliseHeatmapRange() { const today = localDateKey(); const fromInput = $('heatmapFrom'); const toInput = $('heatmapTo'); if (!fromInput || !toInput) return null; fromInput.max = today; toInput.max = today; if (!toInput.value) toInput.value = today; if (!fromInput.value) fromInput.value = dateKeyOffset(toInput.value, -29); if (fromInput.value > toInput.value) [fromInput.value, toInput.value] = [toInput.value, fromInput.value]; if (fromInput.value > today) fromInput.value = today; if (toInput.value > today) toInput.value = today; if (fromInput.value > toInput.value) fromInput.value = toInput.value; return {from: fromInput.value, to: toInput.value}; }
