function drawDailyTimeline() { const canvas = $('dailyTimelineCanvas'); if (!canvas || !dailyPresence) return; const rows = dailyPresence.timeline || []; const rowHeight = 27; const top = 28; const left = 155; const height = Math.max(180, top + rows.length * rowHeight + 28); const {ctx, width} = setupCanvas(canvas, height); const chartWidth = width - left - 12; ctx.font = '10px DM Mono'; ctx.textBaseline = 'middle'; for (let hour = 0; hour <= 24; hour++) { const x = left + chartWidth * hour / 24; ctx.strokeStyle = '#28303d'; ctx.lineWidth = 1; ctx.beginPath(); ctx.moveTo(x, top - 12); ctx.lineTo(x, top + rows.length * rowHeight); ctx.stroke(); if (hour < 24) { ctx.fillStyle = '#7f8999'; ctx.textAlign = hour === 24 ? 'right' : 'center'; ctx.fillText(`${String(hour).padStart(2, '0')}:00`, x, 11); } } rows.forEach((row, index) => { const y = top + index * rowHeight; ctx.fillStyle = index % 2 ? '#10151d' : '#141a23'; ctx.fillRect(0, y - 10, width, 20); ctx.fillStyle = '#d8dee8'; ctx.textAlign = 'left'; ctx.fillText(row.name || row.username, 8, y); (row.spans || []).forEach((span) => { const x = left + chartWidth * span.start_minute / 1440; const spanWidth = chartWidth * (span.end_minute - span.start_minute) / 1440; ctx.fillStyle = dailyColor(span.status); ctx.globalAlpha = .88; ctx.fillRect(x, y - 7, Math.max(2, spanWidth), 14); ctx.globalAlpha = 1; }); ctx.fillStyle = '#7f8999'; ctx.textAlign = 'right'; ctx.fillText(`${Math.round(row.online_minutes || 0)}m`, width - 8, y); }); }
function drawDailyHeatmap() { const canvas = $('dailyHeatmapCanvas'); if (!canvas || !dailyPresence) return; const rows = dailyPresence.heatmap || []; const rowHeight = 25; const top = 31; const left = 155; const height = Math.max(190, top + rows.length * rowHeight + 25); const {ctx, width} = setupCanvas(canvas, height); const chartWidth = width - left - 12; const cellWidth = chartWidth / 24; ctx.font = '10px DM Mono'; ctx.textBaseline = 'middle'; ctx.textAlign = 'center'; for (let hour = 0; hour < 24; hour++) { const x = left + cellWidth * (hour + .5); ctx.fillStyle = '#7f8999'; ctx.fillText(String(hour).padStart(2, '0'), x, 13); } rows.forEach((row, index) => { const y = top + index * rowHeight; ctx.fillStyle = '#d8dee8'; ctx.textAlign = 'left'; ctx.fillText(row.name, 8, y + 9); (row.values || []).forEach((value, hour) => { const intensity = Math.max(0, Math.min(1, Number(value) || 0)); const red = Math.round(23 + intensity * 142); const green = Math.round(31 + intensity * 210); const blue = Math.round(43 + intensity * 70); ctx.fillStyle = `rgb(${red},${green},${blue})`; ctx.fillRect(left + hour * cellWidth + 1, y, Math.max(1, cellWidth - 2), rowHeight - 3); if (cellWidth >= 28 && intensity > .08) { ctx.fillStyle = intensity > .55 ? '#10140d' : '#d8dee8'; ctx.textAlign = 'center'; ctx.fillText(`${Math.round(intensity * 100)}%`, left + cellWidth * (hour + .5), y + 10); } }); }); }
